// Asset manifest: which optional files (models, audio) actually exist.
// assets/manifest.json is generated by `node tools/update-assets.js`.
// If the manifest itself is missing we fall back to "try and fail silently".
let manifestPromise = null;

export function loadManifest() {
  if (!manifestPromise) {
    manifestPromise = fetch("assets/manifest.json")
      .then((r) => (r.ok ? r.json() : null))
      .then((m) => (m ? { models: new Set(m.models || []), audio: new Set(m.audio || []) } : null))
      .catch(() => null);
  }
  return manifestPromise;
}

/** true = listed, false = known missing, null = unknown (no manifest). */
export function hasAsset(manifest, kind, file) {
  if (!manifest) return null;
  return manifest[kind].has(file);
}
